import{_ as a,o as e,c as i,a2 as r}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"kiwa v1.44 リリース — Auth Passwordless UX III 深化 milestone + 縦深化 pair 第 1 pair 3 段拡張達成","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.44/zenn-article.md","filePath":"announcements/v1.44/zenn-article.md"}'),o={name:"announcements/v1.44/zenn-article.md"};function d(s,t,n,l,h,p){return e(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="kiwa-v1-44-リリース-—-auth-passwordless-ux-iii-深化-milestone-縦深化-pair-第-1-pair-3-段拡張達成" tabindex="-1">kiwa v1.44 リリース — Auth Passwordless UX III 深化 milestone + 縦深化 pair 第 1 pair 3 段拡張達成 <a class="header-anchor" href="#kiwa-v1-44-リリース-—-auth-passwordless-ux-iii-深化-milestone-縦深化-pair-第-1-pair-3-段拡張達成" aria-label="Permalink to &quot;kiwa v1.44 リリース — Auth Passwordless UX III 深化 milestone + 縦深化 pair 第 1 pair 3 段拡張達成&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>kiwa v1.44 をリリースしました。 <strong>縦深化 pair 第 1 pair (Auth) 3 段拡張達成</strong> — v1.21 v0.4 (4 protocol adapter) → v1.22 v0.5 (real driver + a11y gate) → v1.44 v0.6 (advanced Passwordless UX 8 axis) の 3 段構造。 pair 第 8 Search v1.14→v1.15→v1.36 に続く 2 例目 pair 深度 3 段記録。</p><h2 id="何が変わったか" tabindex="-1">何が変わったか <a class="header-anchor" href="#何が変わったか" aria-label="Permalink to &quot;何が変わったか&quot;">​</a></h2><h3 id="kiwa-lab-auth-v0-6-0-v0-5-0-→-v0-6-0-minor-bump" tabindex="-1"><code>@kiwa-lab/auth</code> v0.6.0 (v0.5.0 → v0.6.0 minor bump) <a class="header-anchor" href="#kiwa-lab-auth-v0-6-0-v0-5-0-→-v0-6-0-minor-bump" aria-label="Permalink to &quot;`@kiwa-lab/auth` v0.6.0 (v0.5.0 → v0.6.0 minor bump)&quot;">​</a></h3><p>8 個の advanced Passwordless UX axis を追加しました。</p><ul><li><strong>device-bound-passkey</strong> — device bind + credential migration + sync fabric (iCloud Keychain / Chrome Sync / Firefox Sync) + credProps.rk 確認</li><li><strong>conditional-ui</strong> — WebAuthn L3 <code>mediation: &quot;conditional&quot;</code> + autofill hint + fallback ladder + timeout</li><li><strong>step-up-mfa</strong> — NIST SP 800-63B AAL1 → AAL2 → AAL3 escalation ladder + factor 満足 + trust duration cache</li><li><strong>risk-based-auth</strong> — signal aggregation (device / IP / geo / velocity / behavioral) + adaptive challenge + policy chain</li><li><strong>auth-continuity</strong> — seamless re-auth + refresh token rotation + session extension + revocation window</li><li><strong>cross-device-flow</strong> — CTAP2 hybrid transport (caBLE) QR handshake + BLE proximity + tunnel + assertion signature</li><li><strong>session-hijack-detect</strong> — fingerprint drift + geo anomaly + concurrent session + logout cascade</li><li><strong>auth-telemetry</strong> — attempt log + success rate + latency histogram + abuse detection</li></ul><p>3 platform (chromium / webkit / firefox) × 8 axis = 24 cell の fidelity grid。</p><h3 id="_3-dogfood-app-を新規追加" tabindex="-1">3 dogfood app を新規追加 <a class="header-anchor" href="#_3-dogfood-app-を新規追加" aria-label="Permalink to &quot;3 dogfood app を新規追加&quot;">​</a></h3><ul><li><code>examples/dogfood-auth-passwordless-ux-app</code> — 60 tests。 device-bound + conditional-ui + cross-device の 3 axis。</li><li><code>examples/dogfood-auth-step-up-mfa-app</code> — 60 tests。 step-up + continuity + hijack の 3 axis。</li><li><code>examples/dogfood-auth-risk-based-app</code> — 60 tests。 risk + telemetry + hijack (concurrent + geo variant) の 3 axis。</li></ul><h3 id="_3-tutorial-を新規追加" tabindex="-1">3 tutorial を新規追加 <a class="header-anchor" href="#_3-tutorial-を新規追加" aria-label="Permalink to &quot;3 tutorial を新規追加&quot;">​</a></h3><ul><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/97-passwordless-ux" target="_blank" rel="noreferrer">Tutorial 97 — Passwordless UX</a></strong></li><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/98-step-up-mfa" target="_blank" rel="noreferrer">Tutorial 98 — Step-up MFA</a></strong></li><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/99-risk-based-auth" target="_blank" rel="noreferrer">Tutorial 99 — Risk-based auth</a></strong></li></ul><h2 id="_22-milestone-連続-snippet-validation-streak-達成" tabindex="-1">22 milestone 連続 snippet validation streak 達成 <a class="header-anchor" href="#_22-milestone-連続-snippet-validation-streak-達成" aria-label="Permalink to &quot;22 milestone 連続 snippet validation streak 達成&quot;">​</a></h2><p>v1.23 → v1.44 で 22 milestone 連続で tutorial code snippet の validation test を kiwa monorepo 内に配置しています。</p><h2 id="縦深化-pair-pattern-grid" tabindex="-1">縦深化 pair pattern grid <a class="header-anchor" href="#縦深化-pair-pattern-grid" aria-label="Permalink to &quot;縦深化 pair pattern grid&quot;">​</a></h2><p>12 pair が記録されています。 <strong>Pair 1 (Auth) が深度 3 に到達</strong>。</p><table tabindex="0"><thead><tr><th>Pair</th><th>Domain</th><th>Path</th><th>Depth</th></tr></thead><tbody><tr><td><strong>1</strong></td><td><strong>Auth</strong></td><td><strong>v1.21→v1.22→v1.44</strong></td><td><strong>3</strong></td></tr><tr><td>2</td><td>Realtime</td><td>v1.13→v1.28</td><td>2</td></tr><tr><td>3</td><td>Streaming</td><td>v1.20→v1.31</td><td>2</td></tr><tr><td>4</td><td>Database</td><td>v1.14→v1.32</td><td>2</td></tr><tr><td>5</td><td>Payment</td><td>v1.14→v1.19→v1.33→v1.41</td><td>4</td></tr><tr><td>6</td><td>Frontend</td><td>v1.16→v1.34</td><td>2</td></tr><tr><td>7</td><td>Observability</td><td>v1.14→v1.17→v1.35→v1.42</td><td>4</td></tr><tr><td>8</td><td>Search</td><td>v1.14→v1.15→v1.36</td><td>3</td></tr><tr><td>9</td><td>Security</td><td>v1.37→v1.39</td><td>2</td></tr><tr><td>10</td><td>AI/LLM</td><td>v1.12→v1.15→v1.38→v1.40</td><td>4</td></tr><tr><td>11</td><td>Security base</td><td>v1.37</td><td>1</td></tr><tr><td>12</td><td>Edge / Serverless</td><td>v1.43</td><td>1</td></tr></tbody></table><h2 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/auth@^0.6</span></span></code></pre></div><p>Additive-only。 breaking change はありません。</p><h2 id="migration-guide" tabindex="-1">Migration guide <a class="header-anchor" href="#migration-guide" aria-label="Permalink to &quot;Migration guide&quot;">​</a></h2><p><a href="https://cardene777.github.io/kiwa/migrations/v1.43-to-v1.44" target="_blank" rel="noreferrer">v1.43 → v1.44 migration guide</a></p><h2 id="次に何が来るか" tabindex="-1">次に何が来るか <a class="header-anchor" href="#次に何が来るか" aria-label="Permalink to &quot;次に何が来るか&quot;">​</a></h2><p>v1.44 で 5-milestone new-base cadence + 中間 milestone での既存 pair 深化 の 2 段組み rhythm が確立完成。 次回 III 深化 target = 他の pair-2 候補 (Realtime III / Streaming III / Database III / Security III / Frontend III)。 次回 new base = v1.48 前後。</p>',24)])])}const g=a(o,[["render",d]]);export{u as __pageData,g as default};
